import './App.css';
import Footer from './components/Footer/Footer';
import Home from './components/Home/landing';
import Team from './components/TeamPage/TeamSection';
import Faculty from './components/FacultyPage/Faculty';
import Navbar from './components/Navbar/Navbar';
import { useState, useEffect } from 'react';
import LoadingSpinner from './components/LoadingSpinner/LoadingSpinner';
import 'remixicon/fonts/remixicon.css';
import ScrollToTop from './components/ScrollToTop';
import 'remixicon/fonts/remixicon.css';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import EventSection from './components/Events/EventSection';
import EventDetail from './components/Events/EventDetails';
import imageLoader from './utils/imageLoader';

function App() {
  const [loading, setLoading] = useState(true);
  const [showSpinner, setShowSpinner] = useState(true);

  // Define critical images that should load before showing the app
  const criticalImages = [
    'https://i.imgur.com/Lg3kv0j.png', // ECESS Logo
    'https://nitdgp.ac.in/uploads/0507284ec43c705a861174910f4d6d17.JPG', // Landing slide 1
    'https://i.imgur.com/7jLBiUX.jpeg', // Landing slide 2
    'https://i.imgur.com/i8iclAE.jpeg', // Landing slide 3
  ];

  useEffect(() => {
    // Start loading critical images immediately
    loadCriticalResources();
  }, []);

  const loadCriticalResources = async () => {
    try {
      // Preload critical images
      await imageLoader.preloadCriticalImages(criticalImages);

      // Add a small delay to ensure smooth transition
      setTimeout(() => {
        setLoading(false);
      }, 500);
    } catch (error) {
      console.error('Error loading critical resources:', error);
      // Fallback: hide loading after 3 seconds if there's an error
      setTimeout(() => {
        setLoading(false);
      }, 3000);
    }
  };

  const handleSpinnerFinish = () => {
    setShowSpinner(false);
  };

  return (
    <div className="App">
      {showSpinner && (
        <LoadingSpinner 
          isLoading={loading} 
          onFinish={handleSpinnerFinish}
          criticalImages={criticalImages}
        />
      )}
      {!showSpinner && (
        <Router>
          <ScrollToTop/>
          <Navbar />
          <Routes>
            <Route exact path="/" element={<Home />} />
            <Route exact path="/team" element={<Team />} />
            <Route exact path="/faculty" element={<Faculty />} />
            <Route exact path="/events" element={<EventSection />} />
            <Route exact path='/events/:id' element={ <EventDetail />} />
          </Routes>
          <Footer />
        </Router>
      )}
    </div>
  );
}

export default App;
